    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نترجم","math":"الحرف يقسم الأبعاد الثلاثة، إذن هو قاسم مشترك لها"},{"quoi":"نفكّك إلى عوامل أوّلية","math":"<span dir=\"ltr\" class=\"expr\">462 = 2 × 3 × 7 × 11</span> و <span dir=\"ltr\" class=\"expr\">434 = 2 × 7 × 31</span> و <span dir=\"ltr\" class=\"expr\">182 = 2 × 7 × 13</span>"},{"quoi":"ق.م.أ","math":"العوامل المشتركة بأصغر أسّ: <span dir=\"ltr\" class=\"expr\">2 × 7 = 14</span>"},{"quoi":"كل الحلول = قواسم 14","math":"1 و 2 و 7 و 14 ملمتر"},{"quoi":"أكبر حرف ممكن","math":"<span dir=\"ltr\" class=\"expr\">= 14</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نترجم","math":"الحرف يقسم الأبعاد الثلاثة، إذن هو قاسم مشترك لها"},{"quoi":"نفكّك إلى عوامل أوّلية","math":"<span dir=\"ltr\" class=\"expr\">840 = 2<sup>3</sup> × 3 × 5 × 7</span> و <span dir=\"ltr\" class=\"expr\">441 = 3<sup>2</sup> × 7<sup>2</sup></span> و <span dir=\"ltr\" class=\"expr\">420 = 2<sup>2</sup> × 3 × 5 × 7</span>"},{"quoi":"ق.م.أ","math":"العوامل المشتركة بأصغر أسّ: <span dir=\"ltr\" class=\"expr\">3 × 7 = 21</span>"},{"quoi":"كل الحلول = قواسم 21","math":"1 و 3 و 7 و 21 ملمتر"},{"quoi":"أكبر حرف ممكن","math":"<span dir=\"ltr\" class=\"expr\">= 21</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نترجم","math":"الحرف يقسم الأبعاد الثلاثة، إذن هو قاسم مشترك لها"},{"quoi":"نفكّك إلى عوامل أوّلية","math":"<span dir=\"ltr\" class=\"expr\">420 = 2<sup>2</sup> × 3 × 5 × 7</span> و <span dir=\"ltr\" class=\"expr\">180 = 2<sup>2</sup> × 3<sup>2</sup> × 5</span> و <span dir=\"ltr\" class=\"expr\">168 = 2<sup>3</sup> × 3 × 7</span>"},{"quoi":"ق.م.أ","math":"العوامل المشتركة بأصغر أسّ: <span dir=\"ltr\" class=\"expr\">2<sup>2</sup> × 3 = 12</span>"},{"quoi":"كل الحلول = قواسم 12","math":"1 و 2 و 3 و 4 و 6 و 12 ملمتر"},{"quoi":"أكبر حرف ممكن","math":"<span dir=\"ltr\" class=\"expr\">= 12</span>"}],
